			templ_7745c5c3_Err = templruntime.WriteString(templ_7745c5c3_Buffer, 7, "<li><a href=\"#trouble\">Something still is not right</a></li></ul></nav><section class=\"card help\" id=\"add-item\"><h2>Put something on a list</h2><p>Open one of your lists, click <strong>Add item</strong>, and fill in the form. Only <strong>What is it?</strong> has to be filled in — a name and nothing else is a perfectly good item.</p>")
